export const VISUALS: readonly GalleryVisual[] = [
  {"slug":"compression-rarefaction-wave","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"foundations","subtopicTitle":"Foundations: What Sound Is and How We Hear It","conceptSlug":"mechanical-longitudinal-wave","conceptName":"Sound is a mechanical longitudinal wave","line":"Sound propagates by molecules bumping their neighbours — a compression in air is a region of slightly higher pressure where molecules are crowded together; a rarefaction is where they are spread thin. Because the molecules vibrate in the SAME direction the wave travels, the wave is LONGITUDINAL (not transverse, like light or water ripples). And because there have to be molecules to bump each other, sound CANNOT travel through vacuum.","pyqExampleId":"cea49ac8-cf99-458e-aef9-2481bdc07dcd","badge":"picture","interactive":false},
  {"slug":"ear-anatomy","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"foundations","subtopicTitle":"Foundations: What Sound Is and How We Hear It","conceptSlug":"human-ear-chain","conceptName":"The human ear — anatomy chain that converts pressure to nerve impulses","line":"Now that you know what sound IS and how we PERCEIVE it (pitch/loudness/quality), the natural next question is HOW the ear actually does that conversion. The answer is a four-stage chain: outer ear catches sound, the eardrum converts it to mechanical vibration, three tiny bones amplify it, and the cochlea finally converts it to nerve signals. Each stage performs a specific physical transformation — memorise the chain and the NDA recall questions become a lookup.","pyqExampleId":"320c7419-1213-45e6-a2d1-0a001a90a08d","badge":"picture","interactive":false},
  {"slug":"frequency-spectrum-strip","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"wave-equation-and-bands","subtopicTitle":"How We Measure Sound — v = fλ, Speed, and the Frequency Bands","conceptSlug":"frequency-bands-and-scales","conceptName":"Bands and scales — audible / infra / ultrasonic, Mach, sound speeds, decibel, Richter","line":"A handful of named bands and scales come up here every other paper — the audible frequency range (20 Hz – 20 kHz), the ultrasonic threshold, the Mach number labels (subsonic / sonic / supersonic / hypersonic), typical sound speeds in air / water / steel, plus what dB and Richter actually measure. Ultrasonic is just sound above the audible band — same speed in the same medium (per Subtopic 2's speed-medium-only result), shorter wavelength, higher frequency. Memorise the table once and these recall questions become a lookup.","pyqExampleId":"0d4b177e-8cac-45ac-b4f2-af4c27503d3c","badge":"picture","interactive":false},
  {"slug":"echo-geometry","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"sound-behaviours","subtopicTitle":"What Sound DOES — Reflection, Echo, Reverberation, Beats","conceptSlug":"echo-and-minimum-distance","conceptName":"Echo — a single distinct reflection","line":"When you shout at a distant cliff, the sound travels to the cliff, REFLECTS off it, and comes back. If the cliff is far enough away, the reflected sound arrives at your ear AFTER the original has faded — you hear them as two separate sounds, and that's an echo. Too close, and the reflection overlaps the original — you don't perceive an echo at all.","pyqExampleId":"2143d3de-067e-4208-ab03-ca8ae6cb9b35","badge":"picture","interactive":false},
  {"slug":"beats-envelope","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"sound","chapterName":"Sound","subtopicSlug":"sound-behaviours","subtopicTitle":"What Sound DOES — Reflection, Echo, Reverberation, Beats","conceptSlug":"beats-formation","conceptName":"Beats — periodic loud/soft from two close frequencies (interference)","line":"When two sound waves of NEARLY equal frequency are played together, their amplitudes alternately reinforce and cancel as their phases drift in and out of step. You hear a slow PULSING of loudness — \"loud, soft, loud, soft...\". Each pulse is one beat. The further apart the two frequencies, the FASTER the pulsing; if the frequencies are equal, there are no beats at all. Beats are the audible signature of INTERFERENCE — the same wave behaviour that's row 4 of the properties checklist.","pyqExampleId":"0803a1c4-94d4-495a-b059-65b89ebb86db","badge":"picture","interactive":false},
  {"slug":"field-lines-charge","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-electrostatics","subtopicTitle":"Electrostatics: Charges at Rest","conceptSlug":"electric-field-and-lines","conceptName":"Electric field and field lines","line":"Every charge fills the space around it with an electric field — a force-per-unit-charge that a test charge would feel. We draw the field as lines: they start on positive charge and end on negative charge, and the arrow shows the force on a positive test charge.","pyqExampleId":"1b4c54e7-b5e3-45f0-a79c-286e4049c582","badge":"picture","interactive":false},
  {"slug":"iv-characteristic-graph","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-current-and-ohms-law","subtopicTitle":"Electric Current and Ohm's Law","conceptSlug":"ohmic-vs-nonohmic","conceptName":"Ohmic vs non-ohmic conductors","line":"An ohmic device keeps the same resistance whatever the voltage — its I–V graph is a straight line. A non-ohmic device (like a diode or a bulb filament) changes resistance with conditions, so its I–V graph bends.","pyqExampleId":"b3d5f882-2365-4b20-8671-47507358eaba","badge":"picture","interactive":false},
  {"slug":"resistance-wire-geometry","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-resistance-and-resistivity","subtopicTitle":"Resistance and Resistivity","conceptSlug":"resistance-and-its-factors","conceptName":"Resistance and what controls it","line":"A long, thin wire of a poorly conducting material resists current most. Resistance grows with LENGTH (more obstacles to push charge through), falls with cross-section AREA (a wider pipe), and depends on the MATERIAL through its resistivity. It does NOT depend on the current you push through it.","pyqExampleId":"1979f9c0-2e56-405f-ab5a-e946dc59c367","badge":"picture","interactive":false},
  {"slug":"resistors-series-parallel","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-resistor-combinations","subtopicTitle":"Combination of Resistors","conceptSlug":"mixed-networks","conceptName":"Reducing mixed series-parallel networks","line":"Most circuit questions are nested: a parallel cluster sitting inside a series chain, or vice versa. The method is always the same — find the innermost pure-series or pure-parallel group, collapse it to one resistor, redraw, and repeat until a single number is left.","pyqExampleId":"236ae3f2-adad-4223-b7be-00dc076eca63","badge":"picture","interactive":false},
  {"slug":"emf-internal-resistance","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-cells-and-kirchhoff","subtopicTitle":"Cells, EMF and Kirchhoff's Laws","conceptSlug":"emf-and-internal-resistance","conceptName":"EMF, internal resistance and terminal voltage","line":"A real cell isn't a perfect battery — it has its own small internal resistance. The EMF (ε) is the full voltage it would give with no current flowing; once current flows, some voltage is 'lost' inside the cell across its internal resistance, so the voltage you actually get at the terminals is a little less.","badge":"picture","interactive":false},
  {"slug":"bar-magnet-field-lines","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-magnetism-and-effects","subtopicTitle":"Magnetism and Magnetic Effects of Current","conceptSlug":"magnets-and-field-lines","conceptName":"Magnets and magnetic field lines","line":"Every magnet has two poles (north and south) that can't be separated — break a magnet and each piece grows its own pair. We picture the field with lines that leave the north pole, loop around to the south pole OUTSIDE, and continue from south to north INSIDE, forming closed loops that never cross.","pyqExampleId":"7be1aa6e-4192-4648-ad03-05f3f3264d83","badge":"picture","interactive":false},
  {"slug":"magnetic-field-around-wire","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-magnetism-and-effects","subtopicTitle":"Magnetism and Magnetic Effects of Current","conceptSlug":"field-of-a-current","conceptName":"Magnetic field of a current-carrying straight wire","line":"A current makes a magnetic field that wraps around the wire in circles. The bigger the current and the closer you are, the stronger the field — it grows with current and falls off as 1/distance. Point your right thumb along the current and your curled fingers show which way the field circles.","pyqExampleId":"dfa5e77e-b1e1-4355-a12d-beed39351bb1","badge":"picture","interactive":false},
  {"slug":"solenoid-field-lines","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-magnetism-and-effects","subtopicTitle":"Magnetism and Magnetic Effects of Current","conceptSlug":"solenoid-field","conceptName":"Magnetic field of a solenoid","line":"Wind a wire into a tight coil (a solenoid) and the fields of all the turns add up inside to give a strong, UNIFORM field — just like a bar magnet's. Pack in more turns per metre or push more current and the field grows in proportion. Slip a soft-iron core inside and it grows much more.","pyqExampleId":"08ff36d3-a8ff-43e0-8d06-07fd59ea03c2","badge":"picture","interactive":false},
  {"slug":"magnetic-force-triad","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-magnetic-force","subtopicTitle":"Magnetic Force and Fleming's Rules","conceptSlug":"force-on-moving-charge","conceptName":"Force on a charge moving in a magnetic field","line":"A magnetic field only pushes on a charge that is MOVING, and only on the part of the motion that crosses the field. Move straight along the field and you feel nothing; cross it at right angles and the push is maximum. The force is always sideways — perpendicular to both the velocity and the field.","pyqExampleId":"da34f431-ed84-4df3-9ed4-6b17d549b6b1","badge":"try","interactive":true},
  {"slug":"flemings-left-hand-rule","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"electricity-and-magnetism","chapterName":"Electricity and Magnetism","subtopicSlug":"em-magnetic-force","subtopicTitle":"Magnetic Force and Fleming's Rules","conceptSlug":"flemings-left-hand-rule","conceptName":"Force on a current-carrying conductor — Fleming's left-hand rule","line":"A wire carrying current in a magnetic field is really a stream of moving charges, so the field pushes on it too. The force is F = BIL, and its DIRECTION comes from Fleming's LEFT-hand rule — the rule behind every electric motor.","pyqExampleId":"9cb5b633-1bc9-4cc0-9878-de243d998b29","badge":"try","interactive":true},
  {"slug":"opt-concave-mirror-rays","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-reflection-and-mirrors","subtopicTitle":"Reflection and Mirrors","conceptSlug":"concave-mirror-images","conceptName":"Concave mirror — image formation","line":"A concave mirror converges light, so where the image forms — and whether it is real or virtual, enlarged or shrunk — depends entirely on where the object sits relative to F and C. Bring the object closer than F and the image flips to virtual, erect and magnified (that is the shaving/make-up mirror). That is why concave mirrors are used in vehicle headlights — a source at F sends out a parallel beam.","pyqExampleId":"69c3c50a-fe1c-4efb-848f-94365c6a3266","badge":"picture","interactive":false},
  {"slug":"opt-convex-mirror-rays","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-reflection-and-mirrors","subtopicTitle":"Reflection and Mirrors","conceptSlug":"convex-mirror-images","conceptName":"Convex mirror — always virtual, erect, diminished","line":"A convex mirror bulges toward you and spreads light out, so it can never bring rays to a real focus in front of it. Wherever the object is, the image is virtual, the right way up, and smaller — squeezed into the small space between the pole and the focus behind the mirror. Shrinking the scene is exactly what gives a wide field of view, which is why it is the vehicle rear-view mirror.","pyqExampleId":"408ec05e-8c58-4f57-840a-17b9cd2bb746","badge":"picture","interactive":false},
  {"slug":"opt-refraction-tir","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-refraction-and-tir","subtopicTitle":"Refraction, Speed of Light, and Total Internal Reflection","conceptSlug":"total-internal-reflection","conceptName":"Total internal reflection and the critical angle","line":"When light tries to leave a denser medium for a rarer one, it bends away from the normal — and as you increase the incidence angle, the refracted ray tilts further until, at the critical angle, it grazes the surface. Push past that angle and the light cannot escape at all: it is reflected entirely back inside. That all-or-nothing reflection is total internal reflection.","pyqExampleId":"6bb79606-238f-474e-aeb0-e7833627adf9","badge":"picture","interactive":false},
  {"slug":"opt-convex-lens-rays","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-lenses-and-lens-formula","subtopicTitle":"Lenses and the Lens Formula","conceptSlug":"lens-types-and-behaviour","conceptName":"Convex and concave lenses","line":"A convex lens is thick in the middle and squeezes parallel rays to a point — it converges light and can make real images. A concave lens is thin in the middle and fans rays apart — it diverges light and can only ever make a virtual, smaller, upright image. That single fact about the concave lens settles a surprising number of questions.","pyqExampleId":"b32c44eb-6961-4e55-9d08-7315e860e1a9","badge":"picture","interactive":false},
  {"slug":"opt-prism-dispersion","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-prisms-and-dispersion","subtopicTitle":"Prisms and Dispersion","conceptSlug":"refraction-through-a-prism","conceptName":"Refraction through a prism and deviation","line":"A prism is a wedge of glass with two slanted faces. Light entering bends toward the normal at the first face and away from the normal at the second — both bends turn the ray the same way, toward the thick base of the prism. The total turning is the angle of deviation.","pyqExampleId":"de6408d2-3b8b-4c0d-9763-8fe65b305c5d","badge":"picture","interactive":false},
  {"slug":"opt-human-eye","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"light-optics","chapterName":"Light and Optics","subtopicSlug":"opt-eye-and-instruments","subtopicTitle":"The Human Eye and Optical Instruments","conceptSlug":"human-eye-and-accommodation","conceptName":"The human eye and accommodation","line":"The eye works like a camera with a self-adjusting lens. Light enters through the cornea, passes the pupil (whose size the iris controls), and is focused by the crystalline lens onto the retina, forming a real, inverted, diminished image. To keep near and far objects both in focus, the lens changes its own focal length — that automatic refocusing is called accommodation.","pyqExampleId":"4b537bbb-f7f0-48f4-8068-6da868b58fa8","badge":"picture","interactive":false},
  {"slug":"lmf-free-body-diagram","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion and Forces","subtopicSlug":"lmf-newtons-laws","subtopicTitle":"Newton's Three Laws of Motion","conceptSlug":"second-law-f-ma","conceptName":"Second law — F = ma","line":"Push a body and it accelerates: the harder you push, the faster it speeds up, and the heavier it is, the less it speeds up for the same push. The precise statement is that force equals the rate of change of momentum, which for constant mass reduces to the familiar F = ma. Mass is the constant of proportionality between force and acceleration.","pyqExampleId":"30170535-1970-452a-874b-12afbd44eabc","badge":"picture","interactive":false},
  {"slug":"lmf-action-reaction-pair","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion and Forces","subtopicSlug":"lmf-newtons-laws","subtopicTitle":"Newton's Three Laws of Motion","conceptSlug":"third-law-action-reaction","conceptName":"Third law — action and reaction","line":"Forces always come in pairs. When you push on a wall, the wall pushes back on you with an equal force in the opposite direction. A rocket pushes gas backward and the gas pushes the rocket forward. The two forces are equal in size, opposite in direction, and crucially act on DIFFERENT bodies.","badge":"picture","interactive":false},
  {"slug":"lmf-resultant-parallelogram","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion and Forces","subtopicSlug":"lmf-newtons-laws","subtopicTitle":"Newton's Three Laws of Motion","conceptSlug":"resultant-of-forces","conceptName":"Combining forces — the parallelogram law","line":"When several forces act at a point, only their VECTOR sum — the resultant — matters for the motion. For two forces the resultant is the diagonal of the parallelogram they span, and its size depends on the angle between them: largest when they are aligned, smallest when they oppose. This is the chapter's main source of HARD questions.","pyqExampleId":"e4c2aa76-90d7-4d25-9448-d43681c83b6a","badge":"picture","interactive":false},
  {"slug":"lmf-friction-incline","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion and Forces","subtopicSlug":"lmf-friction","subtopicTitle":"Friction","conceptSlug":"limiting-friction","conceptName":"Limiting (maximum) friction, f = μN","line":"Friction adjusts itself to oppose whatever push you apply — up to a maximum. That maximum, the limiting friction, is proportional to how hard the surfaces are pressed together (the normal force), with the constant of proportionality being the coefficient of friction. Heavier or more strongly pressed surfaces grip harder; smoother surfaces (smaller μ) grip less.","pyqExampleId":"3412b519-ba35-4029-a696-91f654836bb4","badge":"picture","interactive":false},
  {"slug":"ht-anomalous-water-expansion","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"heat-thermodynamics","chapterName":"Heat and Thermodynamics","subtopicSlug":"ht-temperature-and-thermometry","subtopicTitle":"Temperature, Scales, and Thermal Expansion","conceptSlug":"thermal-expansion-coefficients","conceptName":"Thermal expansion — linear, areal, and volume coefficients","line":"Heat a solid and it grows in every dimension. A rod gets longer (linear expansion), a sheet grows in area (areal), and a block grows in volume (volume expansion). The three coefficients are not independent — they are locked in a fixed ratio because area is length-squared and volume is length-cubed.","pyqExampleId":"437a4ace-43c9-48bb-9c70-ac17c6d12a39","badge":"picture","interactive":false},
  {"slug":"ht-heat-transfer-modes","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"heat-thermodynamics","chapterName":"Heat and Thermodynamics","subtopicSlug":"ht-heat-calorimetry-specific-heat","subtopicTitle":"Heat, Specific Heat, Calorimetry, and Heat Transfer","conceptSlug":"modes-of-heat-transfer","conceptName":"The three modes of heat transfer — conduction, convection, radiation","line":"Heat moves from hot to cold in exactly three ways. CONDUCTION passes heat molecule-to-molecule through a solid without the molecules travelling. CONVECTION carries heat by the bulk movement of a heated fluid (warm fluid rises, cool sinks). RADIATION sends heat as electromagnetic waves — it needs no medium and travels at the speed of light, which is how the Sun warms the Earth across empty space.","pyqExampleId":"b5f31a99-79ed-41d3-b5de-1ea79b50b803","badge":"picture","interactive":false},
  {"slug":"ht-pv-process-diagram","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"heat-thermodynamics","chapterName":"Heat and Thermodynamics","subtopicSlug":"ht-thermodynamic-processes","subtopicTitle":"Gas Laws and the Laws of Thermodynamics","conceptSlug":"named-processes","conceptName":"Named processes — isothermal, adiabatic, isochoric, isobaric","line":"Each named process fixes ONE thing. Isothermal holds temperature constant; adiabatic exchanges no heat; isochoric (isovolumetric) holds volume constant; isobaric holds pressure constant. For an unfamiliar process given as an equation, the trick is to combine it with \\(PV = nRT\\) and see which variable ends up constant.","pyqExampleId":"55923af6-56f1-42f5-af25-b7f4c28dd58f","badge":"picture","interactive":false},
  {"slug":"mp-photoelectric-setup","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"modern-physics","chapterName":"Modern Physics","subtopicSlug":"mod-photoelectric-effect","subtopicTitle":"Photoelectric Effect: Light as Particles","conceptSlug":"photon-and-energy","conceptName":"The photon — light carries energy in discrete packets E = hf","line":"Before modern physics, light was purely a wave. The photoelectric effect showed light also behaves as a stream of particles called photons. Each photon carries a fixed packet of energy that depends only on the light's frequency: high-frequency light (violet, ultraviolet, X-rays) has high-energy photons; low-frequency light (red, infrared) has low-energy photons. Brightness just means MORE photons, not more energetic ones.","pyqExampleId":"5f711290-1913-4a72-b39f-6b1a393ca1b7","badge":"picture","interactive":false},
  {"slug":"mp-bohr-energy-levels","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"modern-physics","chapterName":"Modern Physics","subtopicSlug":"mod-atomic-structure","subtopicTitle":"Atomic Structure: Models, Shells, and Energy","conceptSlug":"bohr-stable-orbits","conceptName":"Bohr's model — electrons in stable orbits without radiating","line":"Classical physics said an orbiting electron should continuously radiate energy and spiral into the nucleus — but atoms are stable. Niels Bohr fixed this by postulating that electrons can occupy only certain special orbits in which they do NOT radiate energy. An electron only emits or absorbs energy when it jumps between these allowed orbits.","pyqExampleId":"516d40d9-37b7-419c-a0de-7488f1264106","badge":"picture","interactive":false},
  {"slug":"mp-radiation-penetration","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"modern-physics","chapterName":"Modern Physics","subtopicSlug":"mod-nuclear-physics","subtopicTitle":"Nuclear Physics: Fission, Fusion, and Reactors","conceptSlug":"fuel-and-radioactivity","conceptName":"Nuclear fuel, measuring radioactivity, and radiation types","line":"Reactors burn uranium, which is mined from minerals such as pitchblende. Radioactivity — the spontaneous emission of radiation from unstable nuclei — is measured with a Geiger-Müller (GM) counter. The radiation comes in three flavours: alpha, beta, and gamma, ranked by penetrating power gamma > beta > alpha.","pyqExampleId":"0cd920e7-c909-43b9-84cd-a0769d87a91c","badge":"picture","interactive":false},
  {"slug":"kin-velocity-time-graph","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"kinematics","chapterName":"Kinematics and Motion","subtopicSlug":"kin-equations-and-graphs","subtopicTitle":"Equations of Motion and Motion Graphs","conceptSlug":"velocity-time-graph","conceptName":"Reading a velocity-time graph","line":"On a velocity-time graph, how steep the line is tells you the acceleration, and how much area sits under the line tells you the displacement. Uniform acceleration plots as a straight line; uniform velocity plots as a flat horizontal line.","pyqExampleId":"7d2e6aa1-12ae-453b-948c-5ddd9c1ee774","badge":"picture","interactive":false},
  {"slug":"kin-position-time-graph","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"kinematics","chapterName":"Kinematics and Motion","subtopicSlug":"kin-equations-and-graphs","subtopicTitle":"Equations of Motion and Motion Graphs","conceptSlug":"position-time-graph","conceptName":"Reading a position-time graph","line":"On a position-time (x-t) graph the slope is the velocity. A straight line means constant velocity; a curve that gets steeper means the velocity is rising — acceleration. Watch the axis order: if TIME is on the vertical axis and position on the horizontal, the speed is 1/slope, so a steeper line means a SLOWER object.","pyqExampleId":"bceb7f19-5074-4f87-90da-42a4db1af8aa","badge":"picture","interactive":false},
  {"slug":"kin-projectile-parabola","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"kinematics","chapterName":"Kinematics and Motion","subtopicSlug":"kin-projectile","subtopicTitle":"Projectile and Vertical Motion","conceptSlug":"horizontal-projectile","conceptName":"Horizontal projectile — independence of motions","line":"Fire a ball horizontally off a cliff and two things happen at once and independently: it keeps a constant horizontal speed (no horizontal force), while gravity pulls it down exactly as if it had been dropped. The fall time depends only on the height; the horizontal range is that time times the launch speed.","pyqExampleId":"cfec546a-ad71-4be3-982b-968fd8fc8cd7","badge":"picture","interactive":false},
  {"slug":"fluid-pressure-depth","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"fluid-mechanics","chapterName":"Fluid Mechanics and Properties of Matter","subtopicSlug":"flu-pressure-surface-tension","subtopicTitle":"Pressure and Surface Tension","conceptSlug":"flu-pressure-force-per-area","conceptName":"Pressure — force spread over an area","line":"Pressure measures how concentrated a force is. The same weight pressing on a tiny area bites hard (a drawing pin); spread over a large area it barely registers (a flat shoe on snow). Push the same force through a smaller area and the pressure goes up.","pyqExampleId":"11963628-732e-458a-a31b-d22d73770e2e","badge":"picture","interactive":false},
  {"slug":"pascal-hydraulic-press","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"fluid-mechanics","chapterName":"Fluid Mechanics and Properties of Matter","subtopicSlug":"flu-pressure-surface-tension","subtopicTitle":"Pressure and Surface Tension","conceptSlug":"flu-pascal-principle","conceptName":"Pascal's principle — the hydraulic press","line":"Squeeze an enclosed liquid anywhere and the extra pressure shows up everywhere, equally. That is how a small push on a narrow piston lifts a heavy car on a wide piston: the same pressure acting on a bigger area gives a bigger force.","badge":"picture","interactive":false},
  {"slug":"surface-tension-meniscus","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"fluid-mechanics","chapterName":"Fluid Mechanics and Properties of Matter","subtopicSlug":"flu-pressure-surface-tension","subtopicTitle":"Pressure and Surface Tension","conceptSlug":"flu-surface-tension","conceptName":"Surface tension — the skin of a liquid","line":"A liquid surface behaves like a stretched elastic skin. Molecules at the surface are pulled inward by their neighbours, so the surface tries to shrink to the smallest area — that is why droplets are round and a needle can rest on water. Heat the liquid and the skin weakens.","pyqExampleId":"314b5641-7f29-43fb-ba68-035976f70411","badge":"picture","interactive":false},
  {"slug":"archimedes-floating-block","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"fluid-mechanics","chapterName":"Fluid Mechanics and Properties of Matter","subtopicSlug":"flu-buoyancy-density-flotation","subtopicTitle":"Buoyancy, Density and Flotation","conceptSlug":"flu-archimedes-buoyancy","conceptName":"Archimedes' principle and the buoyant force","line":"Lower an object into water and the water pushes up on it. Archimedes saw that this upthrust equals the weight of the water the object shoves aside. Displace more fluid and you get more lift — that is the whole principle.","pyqExampleId":"d421cdf0-c283-4d2e-883b-c1afa244cc04","badge":"picture","interactive":false},
  {"slug":"wep-work-at-angle","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"work-energy-power","chapterName":"Work, Energy and Power","subtopicSlug":"wep-work-and-work-done","subtopicTitle":"Work — Force Times Displacement Times Cosine","conceptSlug":"wep-definition-of-work","conceptName":"What work means in physics — W = F d cos θ","line":"In everyday language, holding a heavy bag is hard work. In physics it is not work at all — nothing moved in the direction of the force. Physics work happens only when a force actually pushes its target through a displacement, and it counts only the part of the force that lies ALONG that displacement.","pyqExampleId":"35727392-73cd-495c-a57a-9ffcf0daa442","badge":"picture","interactive":false},
  {"slug":"wep-energy-conservation-track","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"work-energy-power","chapterName":"Work, Energy and Power","subtopicSlug":"wep-energy-and-conservation","subtopicTitle":"Energy — Kinetic, Potential, and Conservation","conceptSlug":"wep-conservation-of-energy","conceptName":"Conservation of energy — PE converts to KE as a body falls","line":"Drop a ball: at the top it is all potential energy and no motion; at the bottom it is all kinetic energy and no height. Energy is not lost — it simply changes form. On a frictionless path the sum PE + KE is the same at every point.","pyqExampleId":"4af38486-56ea-4dd4-ba91-91a1e07f1768","badge":"picture","interactive":false},
  {"slug":"grav-composite-sphere","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"gravitation","chapterName":"Gravitation","subtopicSlug":"grav-field-and-potential","subtopicTitle":"Gravitational Field and Potential","conceptSlug":"grav-composite-density","conceptName":"Average density of a composite body","line":"When a body is built from parts of different densities — a solid core wrapped in a shell — its average density is the total mass divided by the total volume, not the average of the two densities. Find each part's mass (density × volume), add them, and divide by the whole volume.","pyqExampleId":"182e13e2-d233-4a0f-8794-3a0874173caa","badge":"picture","interactive":false},
  {"slug":"grav-field-vs-potential","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"gravitation","chapterName":"Gravitation","subtopicSlug":"grav-field-and-potential","subtopicTitle":"Gravitational Field and Potential","conceptSlug":"grav-field-vs-potential","conceptName":"Gravitational field versus potential","line":"The gravitational field is the force per unit mass (a vector, the local 'pull'); the potential is the potential energy per unit mass (a scalar, the 'height' in the energy landscape). Two points can sit at the same potential — the same energy height — while the field (the slope) differs between them. Moving a mass between two equal-potential points does no work.","pyqExampleId":"4d93f43a-a8e7-4e18-b343-f858ca2a8fad","badge":"picture","interactive":false},
  {"slug":"grav-kepler-orbit","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"gravitation","chapterName":"Gravitation","subtopicSlug":"grav-orbits-kepler-escape","subtopicTitle":"Orbits, Kepler and Escape","conceptSlug":"grav-keplers-third-law","conceptName":"Kepler's third law — T² ∝ a³","line":"The farther a planet orbits, the longer its year — but not in proportion. Kepler found the square of the orbital period grows as the cube of the orbit size. So a planet four times farther out takes 4^(3/2) = 8 times as long to go round.","pyqExampleId":"214f2065-97d1-4b61-bb00-8a340be70d8e","badge":"picture","interactive":false},
  {"slug":"umd-least-count-ruler","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"units-measurement-dimensions","chapterName":"Units, Measurement and Dimensions","subtopicSlug":"umd-units-and-dimensions","subtopicTitle":"Units, Measurement and Dimensions","conceptSlug":"umd-measurement-precision","conceptName":"Measurement — precision, accuracy and least count","line":"The least count is the smallest division an instrument can read — 1 mm for an ordinary metre scale. A measurement is only as precise as the instrument's least count; recording a value to a finer level than the least count is false precision. Among several readings, the one written consistently with the instrument's least count (here, to the millimetre) is the most precise honest measurement.","pyqExampleId":"087c437b-c786-41a2-8e5c-f7e6761fea78","badge":"picture","interactive":false},
  {"slug":"osc-shm-displacement-time","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"oscillations-waves","chapterName":"Oscillations and Waves","subtopicSlug":"osc-shm-and-waves","subtopicTitle":"Simple Harmonic Motion and General Waves","conceptSlug":"osc-period-frequency-phase","conceptName":"Period, frequency, and phase","line":"The period T is the time for one complete swing; the frequency f is how many swings happen per second, so the two are reciprocals. The phase tells you where in the cycle the particle is. Because the motion repeats exactly every period, two instants look identical — same position and same direction of travel — only when they are a whole number of periods apart.","pyqExampleId":"6e8881e3-d1a9-4d54-a640-0bbc80662861","badge":"picture","interactive":false},
  {"slug":"osc-wave-types","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"oscillations-waves","chapterName":"Oscillations and Waves","subtopicSlug":"osc-shm-and-waves","subtopicTitle":"Simple Harmonic Motion and General Waves","conceptSlug":"osc-general-wave-properties","conceptName":"Shared and unique properties of waves","line":"Sound, ripples on water and light look very different, but as waves they share a common toolkit: each one reflects, each one carries energy from place to place, and each one exerts a pressure on what it hits. The one property that splits them apart is the need for a medium — sound and water waves must travel through matter, while light (an electromagnetic wave) sails happily through empty space.","pyqExampleId":"73896312-e625-4e88-bd60-4836fbdb178d","badge":"picture","interactive":false},
  {"slug":"osc-pendulum-restoring-force","examSlug":"nda","examName":"NDA","subjectName":"Physics","subjectRoute":"nda-physics","subjectDisplay":"NDA Physics","chapterSlug":"oscillations-waves","chapterName":"Oscillations and Waves","subtopicSlug":"osc-simple-pendulum","subtopicTitle":"The Simple Pendulum","conceptSlug":"osc-pendulum-period-law","conceptName":"The pendulum period law T = 2π√(L/g) — mass-independent","line":"The time a pendulum takes for one swing depends on just two things: how long the string is and how strong gravity is. A longer string swings more slowly; stronger gravity swings it faster. What it does NOT depend on is the mass of the bob — a heavy bob and a light bob on equal strings keep perfect time together, because gravity pulls harder on the heavy one but also has more inertia to move.","pyqExampleId":"b8a2ac7a-946f-4bdb-afbe-ea0161d90d58","badge":"picture","interactive":false},
];

